"""Independent, deliberately simple reference implementation for differential testing.
Assumes valid input. Uses naive data structures and full-state snapshots for rollback."""
import json, copy

MAXN = 4611686018427387903

def simulate(cfg, events):
    st = {
        "early": cfg["early"],
        "keep_first": cfg["overlap"] == "first",
        "bufcap": cfg["buffer_packets"],
        "idle": cfg["idle_ms"],
        "lim_b": cfg["max_streams_bidi"],
        "lim_u": cfg["max_streams_uni"],
        "msd": cfg["max_stream_data"],
        "md": cfg["max_data"],
        "clim": cfg["crypto_limit"],
        "sent": cfg["sent"],
        "keys": {"I": "live", "H": "absent", "Z": "live" if cfg["early"] else "absent", "A": "absent"},
        "pn": {"I": set(), "H": set(), "A": set()},
        "queue": [],          # list of dicts
        "streams": {},        # sid -> dict(highest, final_size, reset, stopped, bytes: dict off->int, contig)
        "crypto": {"I": _nc(), "H": _nc(), "A": _nc()},
        "rt": 0,
        "open": True,
        "state": "open", "code": None, "at": None, "src": None, "peer": None,
        "act": 0,
        "results": [],
    }
    for ei, ev in enumerate(events):
        t = ev["t"]
        if st["open"] and st["idle"] and t >= st["act"] + st["idle"]:
            deadline = st["act"] + st["idle"]
            st["open"] = False; st["state"] = "idle"; st["code"] = "IDLE_TIMEOUT"
            st["at"] = deadline; st["src"] = {"event": ei, "packet": None, "frame": None}
            for r in st["queue"]:
                add_res(st, r, "dropped", "CONNECTION_CLOSED", deadline, None)
            st["queue"] = []
        if ev["op"] == "datagram":
            do_dg(st, ei, ev, t)
        elif ev["op"] == "key" and st["open"]:
            do_key(st, ei, ev, t)
    for r in st["queue"]:
        add_res(st, r, "buffered", "NO_KEYS", r["t"], None)
    st["queue"] = []
    return st

def _nc():
    return {"highest": 0, "bytes": {}, "contig": 0}

def add_res(st, rec, status, reason, at, frame):
    st["results"].append({"event": rec["ei"], "packet": rec["pi"], "status": status,
                          "reason": reason, "at_ms": at, "frame": frame})

def do_dg(st, ei, ev, t):
    pkts = ev["packets"]
    if st["open"]:
        for i in range(len(pkts) - 1):
            if pkts[i]["level"] == "A":
                for pi in range(len(pkts)):
                    add_res(st, {"ei": ei, "pi": pi}, "dropped", "LAYOUT", t, None)
                return
    size = ev["bytes"]
    for pi, p in enumerate(pkts):
        rec = {"ei": ei, "pi": pi, "level": p["level"], "pn": p["pn"],
               "auth": p["auth"], "frames": p["frames"], "t": t}
        if not st["open"]:
            add_res(st, rec, "dropped", "CONNECTION_CLOSED", t, None)
            continue
        lv = rec["level"]
        if lv == "I" and size < 1200:
            add_res(st, rec, "dropped", "INITIAL_TOO_SMALL", t, None); continue
        if lv == "Z" and not st["early"]:
            add_res(st, rec, "dropped", "EARLY_REJECTED", t, None); continue
        ks = st["keys"][lv]
        if ks == "discarded":
            add_res(st, rec, "dropped", "KEYS_DISCARDED", t, None); continue
        if ks == "absent":
            if len(st["queue"]) < st["bufcap"]:
                st["queue"].append(rec)
            else:
                add_res(st, rec, "dropped", "BUFFER_FULL", t, None)
            continue
        process(st, rec, t)

def do_key(st, ei, ev, t):
    lv = ev["level"]
    if ev["action"] == "discard":
        st["keys"][lv] = "discarded"
        rest = []
        for r in st["queue"]:
            if r["level"] == lv:
                add_res(st, r, "dropped", "KEYS_DISCARDED", t, None)
            else:
                rest.append(r)
        st["queue"] = rest
    else:
        if st["keys"][lv] == "absent":
            st["keys"][lv] = "live"
            matched = [r for r in st["queue"] if r["level"] == lv]
            st["queue"] = [r for r in st["queue"] if r["level"] != lv]
            for r in matched:
                if st["open"]:
                    process(st, r, t)
                else:
                    add_res(st, r, "dropped", "CONNECTION_CLOSED", t, None)

ALLOWED = {"PADDING": "IHZA", "PING": "IHZA", "ACK": "IHA", "CRYPTO": "IHA",
           "STREAM": "ZA", "RESET_STREAM": "ZA", "STOP_SENDING": "ZA", "HANDSHAKE_DONE": ""}

def process(st, rec, t):
    if not rec["auth"]:
        add_res(st, rec, "dropped", "AUTH", t, None); return
    space = "A" if rec["level"] in ("A", "Z") else rec["level"]
    pn = rec["pn"]
    if pn in st["pn"][space]:
        add_res(st, rec, "duplicate", "DUPLICATE", t, None); return
    frames = rec["frames"]
    if not frames:
        fail(st, rec, "FRAME_ENCODING_ERROR", t, None); return
    lv = rec["level"]
    for fi, fr in enumerate(frames):
        ty = fr["type"]
        if ty == "UNKNOWN":
            fail(st, rec, "FRAME_ENCODING_ERROR", t, fi); return
        if ty == "CLOSE":
            if fr["app"] and lv not in ("Z", "A"):
                fail(st, rec, "PROTOCOL_VIOLATION", t, fi); return
        elif lv not in ALLOWED[ty]:
            fail(st, rec, "PROTOCOL_VIOLATION", t, fi); return
    snap = copy.deepcopy({k: st[k] for k in ("streams", "crypto", "rt")})
    close = None
    for fi, fr in enumerate(frames):
        if fr["type"] == "CLOSE":
            close = (fi, fr); break
        err = apply(st, fr, lv)
        if err is not None:
            for k in ("streams", "crypto", "rt"):
                st[k] = snap[k]
            fail(st, rec, err, t, fi); return
    st["pn"][space].add(pn)
    st["act"] = t
    add_res(st, rec, "accepted", "OK", t, None)
    if close is not None:
        fi, fr = close
        code = "PEER_APPLICATION_CLOSE" if fr["app"] else "PEER_TRANSPORT_CLOSE"
        st["open"] = False; st["state"] = "closed"; st["code"] = code
        st["at"] = t
        st["src"] = {"event": rec["ei"], "packet": rec["pi"], "frame": fi}
        st["peer"] = fr["code"]
        for r in st["queue"]:
            add_res(st, r, "dropped", "CONNECTION_CLOSED", t, None)
        st["queue"] = []

def fail(st, rec, code, t, fi):
    st["open"] = False; st["state"] = "closed"; st["code"] = code; st["at"] = t
    st["src"] = {"event": rec["ei"], "packet": rec["pi"], "frame": fi}
    st["peer"] = None
    add_res(st, rec, "error", code, t, fi)
    for r in st["queue"]:
        add_res(st, r, "dropped", "CONNECTION_CLOSED", t, None)
    st["queue"] = []

def get_stream(st, sid):
    if sid not in st["streams"]:
        st["streams"][sid] = {"highest": 0, "final_size": None, "reset": False,
                              "stopped": False, "bytes": {}, "contig": 0}
    return st["streams"][sid]

def store_bytes(store, off, data, keep_first):
    for i, b in enumerate(data):
        p = off + i
        if p in store:
            if store[p] != b and not keep_first:
                return "PROTOCOL_VIOLATION"
        else:
            store[p] = b
    return None

def advance(store_obj):
    c = store_obj["contig"]
    while c in store_obj["bytes"]:
        c += 1
    store_obj["contig"] = c

def apply(st, fr, lv):
    ty = fr["type"]
    if ty in ("PADDING", "PING"):
        return None
    if ty == "ACK":
        rng = fr["ranges"]
        if not rng:
            return "FRAME_ENCODING_ERROR"
        prev = None
        for lo, hi in rng:
            if lo > hi:
                return "FRAME_ENCODING_ERROR"
            if prev is not None and lo <= prev + 1:
                return "FRAME_ENCODING_ERROR"
            prev = hi
        sent = st["sent"][lv]
        for lo, hi in rng:
            for x, y in sent:
                pass
            # naive symbolic coverage check
            cur = lo
            while cur <= hi:
                found = None
                for x, y in sent:
                    if x <= cur <= y:
                        found = (x, y); break
                if found is None:
                    return "PROTOCOL_VIOLATION"
                if found[1] >= hi:
                    cur = hi + 1
                else:
                    cur = found[1] + 1
        return None
    if ty == "CRYPTO":
        data = bytes.fromhex(fr["data_hex"])
        off = fr["offset"]; end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        if end > st["clim"]:
            return "CRYPTO_BUFFER_EXCEEDED"
        obj = st["crypto"][lv]
        err = store_bytes(obj["bytes"], off, data, st["keep_first"])
        if err: return err
        obj["highest"] = max(obj["highest"], end)
        advance(obj)
        return None
    if ty == "STREAM":
        sid = fr["id"]; m = sid % 4
        if m not in (0, 2):
            return "STREAM_STATE_ERROR"
        lim = st["lim_b"] if m == 0 else st["lim_u"]
        if sid // 4 + 1 > lim:
            return "STREAM_LIMIT_ERROR"
        s = get_stream(st, sid)
        data = bytes.fromhex(fr["data_hex"])
        off = fr["offset"]; end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        if s["final_size"] is not None:
            if end > s["final_size"] or (fr["fin"] and end != s["final_size"]):
                return "FINAL_SIZE_ERROR"
        if fr["fin"] and end < s["highest"]:
            return "FINAL_SIZE_ERROR"
        if end > st["msd"]:
            return "FLOW_CONTROL_ERROR"
        nh = max(s["highest"], end)
        if st["rt"] - s["highest"] + nh > st["md"]:
            return "FLOW_CONTROL_ERROR"
        if not s["reset"]:
            err = store_bytes(s["bytes"], off, data, st["keep_first"])
            if err: return err
        if nh > s["highest"]:
            st["rt"] += nh - s["highest"]
            s["highest"] = nh
        if fr["fin"]:
            s["final_size"] = end
        advance(s)
        return None
    if ty == "RESET_STREAM":
        sid = fr["id"]; m = sid % 4
        if m not in (0, 2):
            return "STREAM_STATE_ERROR"
        lim = st["lim_b"] if m == 0 else st["lim_u"]
        if sid // 4 + 1 > lim:
            return "STREAM_LIMIT_ERROR"
        s = get_stream(st, sid)
        fs = fr["final_size"]
        if s["final_size"] is not None and s["final_size"] != fs:
            return "FINAL_SIZE_ERROR"
        if fs < s["highest"]:
            return "FINAL_SIZE_ERROR"
        if fs > st["msd"]:
            return "FLOW_CONTROL_ERROR"
        nh = max(s["highest"], fs)
        if st["rt"] - s["highest"] + nh > st["md"]:
            return "FLOW_CONTROL_ERROR"
        if nh > s["highest"]:
            st["rt"] += nh - s["highest"]
            s["highest"] = nh
        s["final_size"] = fs
        s["reset"] = True
        return None
    if ty == "STOP_SENDING":
        sid = fr["id"]
        if sid % 4 != 0:
            return "STREAM_STATE_ERROR"
        if sid // 4 + 1 > st["lim_b"]:
            return "STREAM_LIMIT_ERROR"
        s = get_stream(st, sid)
        s["stopped"] = True
        return None
    return None

def build(tid, st):
    res = sorted(st["results"], key=lambda r: (r["event"], r["packet"]))
    streams = []
    for sid in sorted(st["streams"]):
        s = st["streams"][sid]
        hx = "".join("%02x" % s["bytes"][i] for i in range(s["contig"]))
        streams.append({"id": sid, "highest": s["highest"], "final_size": s["final_size"],
                        "reset": s["reset"], "stopped": s["stopped"], "delivered_hex": hx})
    crypto = []
    for lv in ("I", "H", "A"):
        c = st["crypto"][lv]
        crypto.append({"level": lv, "highest": c["highest"],
                       "contiguous_hex": "".join("%02x" % c["bytes"][i] for i in range(c["contig"]))})
    return {"id": tid, "packets": res,
            "connection": {"state": st["state"], "code": st["code"], "at_ms": st["at"],
                           "source": st["src"], "peer_code": st["peer"],
                           "last_activity_ms": st["act"]},
            "keys": st["keys"], "received_total": st["rt"],
            "streams": streams, "crypto": crypto}

def run(doc):
    out = []
    for tr in doc["traces"]:
        st = simulate(tr["config"], tr["events"])
        out.append(build(tr["id"], st))
    return {"version": 1, "results": out}
